export default function InputPermutations() {
  return (
    <>
      <h1>Input permutations</h1>
      <ScreenshotArea>
        <PermutationsView
          permutations={permutations}
          render={permutation => (
            <Input
              ariaLabel="Input field"
              clearAriaLabel="Clear"
              onChange={() => {
                /*empty handler to suppress react controlled property warning*/
              }}
              {...permutation}
            />
          )}
        />
      </ScreenshotArea>
    </>
  );
}

